import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.functions.MapFunction;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.KeyedProcessFunction;
import org.apache.flink.streaming.api.functions.sink.RichSinkFunction;
import org.apache.flink.streaming.api.functions.source.SourceFunction;
import org.apache.flink.util.Collector;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Serializable;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import java.time.Duration;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    private static final class StageInputEvent implements Serializable {
        public long jobId;
        public long timestampMillis;
        public boolean isSubmit;
        public boolean isJobTerminal;

        public StageInputEvent() {
        }

        public static StageInputEvent submit(TaskEvent e) {
            StageInputEvent out = new StageInputEvent();
            out.jobId = e.jobId;
            out.timestampMillis = e.timestampMillis();
            out.isSubmit = true;
            out.isJobTerminal = false;
            return out;
        }

        public static StageInputEvent terminal(JobEvent e) {
            StageInputEvent out = new StageInputEvent();
            out.jobId = e.jobId;
            out.timestampMillis = e.timestampMillis();
            out.isSubmit = false;
            out.isJobTerminal = true;
            return out;
        }
    }

    private static final class TaskEventSource implements SourceFunction<TaskEvent> {
        private final String path;
        private volatile boolean running = true;

        private TaskEventSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<TaskEvent> ctx) throws Exception {
            try (InputStream fileIn = Files.newInputStream(Paths.get(path));
                 InputStream in = path.endsWith(".gz") ? new GZIPInputStream(fileIn) : fileIn;
                 BufferedReader br = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
                String line;
                while (running && (line = br.readLine()) != null) {
                    if (line.isEmpty()) {
                        continue;
                    }
                    String[] parts = line.split(",", -1);
                    if (parts.length < 6) {
                        continue;
                    }
                    long tsMicros = parseLong(parts[0]);
                    long jobId = parseLong(parts[2]);
                    int taskIndex = parseInt(parts[3]);
                    int eventType = parseInt(parts[5]);
                    ctx.collect(new TaskEvent(tsMicros, jobId, taskIndex, eventType));
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    private static final class JobEventSource implements SourceFunction<JobEvent> {
        private final String path;
        private volatile boolean running = true;

        private JobEventSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<JobEvent> ctx) throws Exception {
            try (InputStream fileIn = Files.newInputStream(Paths.get(path));
                 InputStream in = path.endsWith(".gz") ? new GZIPInputStream(fileIn) : fileIn;
                 BufferedReader br = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8))) {
                String line;
                while (running && (line = br.readLine()) != null) {
                    if (line.isEmpty()) {
                        continue;
                    }
                    String[] parts = line.split(",", -1);
                    if (parts.length < 4) {
                        continue;
                    }
                    long tsMicros = parseLong(parts[0]);
                    long jobId = parseLong(parts[2]);
                    int eventType = parseInt(parts[3]);
                    ctx.collect(new JobEvent(tsMicros, jobId, eventType));
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    private static final class LocalFileSink extends RichSinkFunction<String> {
        private final String outputPath;
        private transient java.io.BufferedWriter writer;

        private LocalFileSink(String outputPath) {
            this.outputPath = outputPath;
        }

        @Override
        public void open(Configuration parameters) throws Exception {
            Path p = Paths.get(outputPath);
            Path parent = p.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            writer = Files.newBufferedWriter(
                    p,
                    StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE,
                    StandardOpenOption.TRUNCATE_EXISTING,
                    StandardOpenOption.WRITE);
        }

        @Override
        public synchronized void invoke(String value, Context context) throws Exception {
            writer.write(value);
            writer.newLine();
        }

        @Override
        public void close() throws Exception {
            if (writer != null) {
                writer.flush();
                writer.close();
            }
        }
    }

    private static final class StageCounter extends KeyedProcessFunction<Long, StageInputEvent, Tuple2<Long, Integer>> {
        private final long inactivityGapMillis;

        private transient ValueState<Integer> currentCount;
        private transient ValueState<Integer> maxCount;
        private transient ValueState<Long> currentTimer;

        private StageCounter(long inactivityGapMillis) {
            this.inactivityGapMillis = inactivityGapMillis;
        }

        @Override
        public void open(Configuration parameters) {
            currentCount = getRuntimeContext().getState(new ValueStateDescriptor<>("currentCount", Integer.class));
            maxCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxCount", Integer.class));
            currentTimer = getRuntimeContext().getState(new ValueStateDescriptor<>("currentTimer", Long.class));
        }

        @Override
        public void processElement(StageInputEvent value, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            if (value.isSubmit) {
                Integer cur = currentCount.value();
                if (cur == null) {
                    cur = 0;
                }
                cur += 1;
                currentCount.update(cur);

                long timerTs = value.timestampMillis + inactivityGapMillis;
                Long oldTimer = currentTimer.value();
                if (oldTimer != null) {
                    ctx.timerService().deleteEventTimeTimer(oldTimer);
                }
                currentTimer.update(timerTs);
                ctx.timerService().registerEventTimeTimer(timerTs);
                return;
            }

            if (value.isJobTerminal) {
                finalizeStageIfNeeded();
                Integer max = maxCount.value();
                if (max == null) {
                    max = 0;
                }
                out.collect(Tuple2.of(value.jobId, max));

                Long timer = currentTimer.value();
                if (timer != null) {
                    ctx.timerService().deleteEventTimeTimer(timer);
                }
                currentCount.clear();
                maxCount.clear();
                currentTimer.clear();
            }
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            Long timer = currentTimer.value();
            if (timer != null && timer == timestamp) {
                finalizeStageIfNeeded();
                currentCount.clear();
                currentTimer.clear();
            }
        }

        private void finalizeStageIfNeeded() throws Exception {
            Integer cur = currentCount.value();
            if (cur == null) {
                cur = 0;
            }
            Integer max = maxCount.value();
            if (max == null) {
                max = 0;
            }
            if (cur > max) {
                maxCount.update(cur);
            }
        }
    }

    private static long parseLong(String s) {
        if (s == null || s.isEmpty()) {
            return 0L;
        }
        return Long.parseLong(s);
    }

    private static int parseInt(String s) {
        if (s == null || s.isEmpty()) {
            return 0;
        }
        return Integer.parseInt(s);
    }

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        final int sesssizeSeconds = params.getInt("sesssize", 600);

        if (taskInput == null || jobInput == null || outputPath == null) {
            throw new IllegalArgumentException("Required parameters: --task_input --job_input --output");
        }

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        DataStream<TaskEvent> tasks = env
                .addSource(taskSourceOrTest(new TaskEventSource(taskInput)))
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<TaskEvent>forBoundedOutOfOrderness(Duration.ofMinutes(1))
                                .withTimestampAssigner((e, ts) -> e.timestampMillis()));

        DataStream<JobEvent> jobs = env
                .addSource(jobSourceOrTest(new JobEventSource(jobInput)))
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<JobEvent>forBoundedOutOfOrderness(Duration.ofMinutes(1))
                                .withTimestampAssigner((e, ts) -> e.timestampMillis()));

        DataStream<StageInputEvent> submits = tasks
                .filter(e -> e.eventType == TaskEvent.SUBMIT)
                .map((MapFunction<TaskEvent, StageInputEvent>) StageInputEvent::submit);

        DataStream<StageInputEvent> terminals = jobs
                .filter(JobEvent::isTerminal)
                .map((MapFunction<JobEvent, StageInputEvent>) StageInputEvent::terminal);

        DataStream<Tuple2<Long, Integer>> result = submits
                .union(terminals)
                .keyBy(e -> e.jobId)
                .process(new StageCounter(sesssizeSeconds * 1000L));

        result
                .map(t -> String.format("(%d,%d)", t.f0, t.f1))
                .addSink((org.apache.flink.streaming.api.functions.sink.SinkFunction<String>) sinkOrTest(new LocalFileSink(outputPath)))
                .setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

}
"}

