                currentCount.clear();
                currentTimer.clear();
            }
        }

        private void finalizeStageIfNeeded() throws Exception {
            Integer cur = currentCount.value();
            if (cur == null) {
                cur = 0;
            }
            Integer max = maxCount.value();
            if (max == null) {
                max = 0;
            }
            if (cur > max) {
                maxCount.update(cur);
            }
        }
    }

    private static long parseLong(String s) {
        if (s == null || s.isEmpty()) {
            return 0L;
        }
        return Long.parseLong(s);
    }

    private static int parseInt(String s) {
        if (s == null || s.isEmpty()) {
            return 0;
        }
        return Integer.parseInt(s);
    }

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        final int sesssizeSeconds = params.getInt("sesssize", 600);

        if (taskInput == null || jobInput == null || outputPath == null) {
            throw new IllegalArgumentException("Required parameters: --task_input --job_input --output");
        }

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        DataStream<TaskEvent> tasks = env
                .addSource(taskSourceOrTest(new TaskEventSource(taskInput)))
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<TaskEvent>forBoundedOutOfOrderness(Duration.ofMinutes(1))
                                .withTimestampAssigner((e, ts) -> e.timestampMillis()));

        DataStream<JobEvent> jobs = env
                .addSource(jobSourceOrTest(new JobEventSource(jobInput)))
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<JobEvent>forBoundedOutOfOrderness(Duration.ofMinutes(1))
                                .withTimestampAssigner((e, ts) -> e.timestampMillis()));

        DataStream<StageInputEvent> submits = tasks
                .filter(e -> e.eventType == TaskEvent.SUBMIT)
                .map((MapFunction<TaskEvent, StageInputEvent>) StageInputEvent::submit);

        DataStream<StageInputEvent> terminals = jobs
                .filter(JobEvent::isTerminal)
                .map((MapFunction<JobEvent, StageInputEvent>) StageInputEvent::terminal);

        DataStream<Tuple2<Long, Integer>> result = submits
                .union(terminals)
                .keyBy(e -> e.jobId)
                .process(new StageCounter(sesssizeSeconds * 1000L));

        result
                .map(t -> String.format("(%d,%d)", t.f0, t.f1))
                .addSink((org.apache.flink.streaming.api.functions.sink.SinkFunction<String>) sinkOrTest(new LocalFileSink(outputPath)))
                .setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

}
