        @Override
        public void processElement(StageInputEvent value, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            if (value.isSubmit) {
                Integer cur = currentCount.value();
                if (cur == null) {
                    cur = 0;
