   173	    private static final class StageCounter extends KeyedProcessFunction<Long, StageInputEvent, Tuple2<Long, Integer>> {
   174	        private final long inactivityGapMillis;
   175	
   176	        private transient ValueState<Integer> currentCount;
   177	        private transient ValueState<Integer> maxCount;
   178	        private transient ValueState<Long> currentTimer;
   179	
   180	        private StageCounter(long inactivityGapMillis) {
   181	            this.inactivityGapMillis = inactivityGapMillis;
   182	        }
   183	
   184	        @Override
   185	        public void open(Configuration parameters) {
   186	            currentCount = getRuntimeContext().getState(new ValueStateDescriptor<>("currentCount", Integer.class));
   187	            maxCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxCount", Integer.class));
   188	            currentTimer = getRuntimeContext().getState(new ValueStateDescriptor<>("currentTimer", Long.class));
   189	        }
   190	
   191	        @Override
   192	        public void processElement(StageInputEvent value, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
   193	            if (value.isSubmit) {
   194	                Integer cur = currentCount.value();
   195	                if (cur == null) {
   196	                    cur = 0;
   197	                }
   198	                cur += 1;
   199	                currentCount.update(cur);
   200	
   201	                long timerTs = value.timestampMillis + inactivityGapMillis;
   202	                Long oldTimer = currentTimer.value();
   203	                if (oldTimer != null) {
   204	                    ctx.timerService().deleteEventTimeTimer(oldTimer);
   205	                }
   206	                currentTimer.update(timerTs);
   207	                ctx.timerService().registerEventTimeTimer(timerTs);
   208	                return;
   209	            }
   210	
   211	            if (value.isJobTerminal) {
   212	                finalizeStageIfNeeded();
