   214	                if (max == null) {
   215	                    max = 0;
   216	                }
   217	                out.collect(Tuple2.of(value.jobId, max));
   218	
   219	                Long timer = currentTimer.value();
   220	                if (timer != null) {
   221	                    ctx.timerService().deleteEventTimeTimer(timer);
   222	                }
   223	                currentCount.clear();
   224	                maxCount.clear();
   225	                currentTimer.clear();
   226	            }
   227	        }
