   229	        @Override
   230	        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
   231	            Long timer = currentTimer.value();
   232	            if (timer != null && timer == timestamp) {
   233	                finalizeStageIfNeeded();
   234	                currentCount.clear();
   235	                currentTimer.clear();
   236	            }
   237	        }
