   239	        private void finalizeStageIfNeeded() throws Exception {
   240	            Integer cur = currentCount.value();
   241	            if (cur == null) {
   242	                cur = 0;
   243	            }
   244	            Integer max = maxCount.value();
   245	            if (max == null) {
   246	                max = 0;
   247	            }
   248	            if (cur > max) {
   249	                maxCount.update(cur);
